insert into public.products
  (id, name_en, name_kn, category, price_per_kg, stock_kg, badge, image_url,
   description_en, description_kn, tip_en, tip_kn, shelf_life_en, shelf_life_kn, alt_names, sort_order)
values
  ('prawn-dry', 'Dried Prawns', 'ಒಣ ಸಿಗಡಿ', 'prawn', 1400, 12, 'best', null, 'Cleaned, sun-dried prawns. Great in chutney powder, curries and pulao.', 'ಸ್ವಚ್ಛಗೊಳಿಸಿದ, ಬಿಸಿಲಿನಲ್ಲಿ ಒಣಗಿಸಿದ ಸಿಗಡಿ. ಚಟ್ನಿ ಪುಡಿ, ಸಾರು ಮತ್ತು ಪುಲಾವ್‌ಗೆ ಉತ್ತಮ.', 'Dry-roast lightly and grind with coconut and chillies for chutney powder.', 'ಸ್ವಲ್ಪ ಹುರಿದು, ತೆಂಗಿನಕಾಯಿ ಮತ್ತು ಮೆಣಸಿನಕಾಯಿಯೊಂದಿಗೆ ರುಬ್ಬಿ ಚಟ್ನಿ ಪುಡಿ ಮಾಡಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['sigadi', 'shrimp', 'konju']::text[], 10),
  ('bombay-duck', 'Bombay Duck (Bombil)', 'ಬೊಂಬಿಲ್', 'special', 900, 8, 'new', null, 'Soft, fully dried Bombay duck. Best fried crisp or added to curries.', 'ಮೃದುವಾದ, ಸಂಪೂರ್ಣ ಒಣಗಿಸಿದ ಬೊಂಬಿಲ್. ಕರಿದು ಅಥವಾ ಸಾರಿನಲ್ಲಿ ಹಾಕಿ ಸವಿಯಿರಿ.', 'Shallow fry until crisp and serve with rice and rasam or dal.', 'ಗರಿಗರಿಯಾಗುವವರೆಗೆ ಕರಿದು, ಅನ್ನ ಮತ್ತು ಸಾರಿನೊಂದಿಗೆ ಬಡಿಸಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['bombil', 'bummalo']::text[], 20),
  ('mackerel-dry', 'Dried Mackerel', 'ಒಣ ಬಂಗುಡೆ', 'fish', 700, 20, 'best', null, 'Salted and sun-dried mackerel. Rich, strong flavour for coastal curries.', 'ಉಪ್ಪು ಹಚ್ಚಿ ಬಿಸಿಲಿನಲ್ಲಿ ಒಣಗಿಸಿದ ಬಂಗುಡೆ. ಕರಾವಳಿ ಶೈಲಿಯ ಸಾರಿಗೆ ಅತ್ಯುತ್ತಮ.', 'Soak in warm water for 15 minutes to remove extra salt, then cook in a tamarind curry.', 'ಹೆಚ್ಚುವರಿ ಉಪ್ಪು ಹೋಗಲು 15 ನಿಮಿಷ ಬೆಚ್ಚಗಿನ ನೀರಿನಲ್ಲಿ ನೆನೆಸಿ, ನಂತರ ಹುಣಸೆಹಣ್ಣಿನ ಸಾರಿನಲ್ಲಿ ಬೇಯಿಸಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['bangude', 'bangda', 'ayala']::text[], 30),
  ('sardine-dry', 'Dried Sardine', 'ಒಣ ಬೂತಾಯಿ', 'fish', 450, 25, null, null, 'Small sun-dried sardines. Budget-friendly and perfect for fry or thokku.', 'ಸಣ್ಣ ಬಿಸಿಲಿನಲ್ಲಿ ಒಣಗಿಸಿದ ಬೂತಾಯಿ. ಕಡಿಮೆ ಬೆಲೆ, ಫ್ರೈ ಮತ್ತು ತೊಕ್ಕಿಗೆ ಸೂಕ್ತ.', 'Fry with onion and chilli powder, or make a spicy thokku.', 'ಈರುಳ್ಳಿ ಮತ್ತು ಮೆಣಸಿನ ಪುಡಿಯೊಂದಿಗೆ ಕರಿಯಿರಿ, ಅಥವಾ ಖಾರದ ತೊಕ್ಕು ಮಾಡಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['boothai', 'mathi', 'chala']::text[], 40),
  ('seer-dry', 'Dried Seer Fish', 'ಒಣ ಅಂಜಲ್', 'special', 1800, 5, 'premium', null, 'Thick seer fish slices, carefully dried. A premium pick for special meals.', 'ದಪ್ಪ ಅಂಜಲ್ ತುಂಡುಗಳು, ಜಾಗರೂಕತೆಯಿಂದ ಒಣಗಿಸಲಾಗಿದೆ. ವಿಶೇಷ ಊಟಕ್ಕೆ ಉತ್ತಮ ಆಯ್ಕೆ.', 'Soak briefly, then shallow fry with masala or add to a coconut curry.', 'ಸ್ವಲ್ಪ ಹೊತ್ತು ನೆನೆಸಿ, ಮಸಾಲೆಯೊಂದಿಗೆ ಕರಿಯಿರಿ ಅಥವಾ ತೆಂಗಿನಕಾಯಿ ಸಾರಿಗೆ ಹಾಕಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['anjal', 'surmai', 'king fish', 'vanjaram']::text[], 50),
  ('pomfret-dry', 'Dried Pomfret', 'ಒಣ ಮಾಂಜಿ', 'fish', 1600, 0, null, null, 'Flat, mild-tasting pomfret, dried whole. Currently out of stock.', 'ಸೌಮ್ಯ ರುಚಿಯ ಮಾಂಜಿ, ಪೂರ್ಣವಾಗಿ ಒಣಗಿಸಲಾಗಿದೆ. ಸದ್ಯ ಲಭ್ಯವಿಲ್ಲ.', 'Shallow fry whole with a little turmeric and salt.', 'ಸ್ವಲ್ಪ ಅರಿಶಿನ ಮತ್ತು ಉಪ್ಪಿನೊಂದಿಗೆ ಪೂರ್ತಿ ಕರಿಯಿರಿ.', 'Best within 3 months if stored airtight', 'ಗಾಳಿಯಾಡದಂತೆ ಇಟ್ಟರೆ 3 ತಿಂಗಳೊಳಗೆ ಬಳಸಿ', array['manji', 'paplet', 'pomfret']::text[], 60)
on conflict (id) do nothing;
